### Cross validation ####import pandas as pdimport numpy as npfrom sklearn.metrics import mutual_info_scorefrom collections import Counterfrom tqdm import tqdmfrom scipy.io import mmread expression_matrix = mmread("/Users/ggraham/MERFISH/2025_10_06_genes_meeting_criteria.mtx")""" here, rows are genes (unlabeled) and columns are cells,all of the genes listed here are marker genes that fit Duncans criteriato save computation"""expression_matrix = pd.DataFrame(expression_matrix.toarray())"convert to a dataframe"genes = pd.read_csv("/Users/ggraham/MERFISH/2025_10_06_sparse_mat_rownames.csv")genes = genes['x']"""genes corresponds to the genes (rows) in expression matrix"""clusters = pd.read_csv("/Users/ggraham/MERFISH/2025_10_06_clusters.csv")"""clusters['clusters'] corresponds to the cluster label for each cell"""# Set up data structure like the originalexpression_matrix.index = genes  # Set gene names as index# Create labels dataframe - make sure cell names match expression matrix columnscell_names = expression_matrix.columns df_labels = pd.DataFrame({    'label': clusters['clusters'].values,    'cell_label': cell_names}, index=cell_names)#read in seurat marker genesNSmarkers =pd.read_csv("/Users/ggraham/MERFISH/NSForest Output/final_clusters2_markers.csv")ns_genes = NSmarkers['markerGene']## machine learning time babeyfrom sklearn.model_selection import cross_val_score, StratifiedKFoldfrom sklearn.ensemble import RandomForestClassifierfrom sklearn.metrics import accuracy_scoreimport numpy as np    #pval # Prepare data - transpose so cells are rows, genes are columnsns_X = expression_matrix.loc[ns_genes].Tns_y = df_labels['label']# Initialize classifierns_clf = RandomForestClassifier(n_estimators=100, random_state=42)# Perform cross-validationns_cv = StratifiedKFold(n_splits=5, shuffle=True, random_state=42)ns_cv_scores = cross_val_score(ns_clf, ns_X, ns_y, cv=ns_cv, scoring='accuracy')# Calculate metricsnp.mean(ns_cv_scores)np.std(ns_cv_scores)